import { describe, expect, it } from 'vitest';
import { computeProfile } from '../flavor/profile';
import type { TasteVector } from '../flavor/tastes';
import { drinksResponse, engineFingerprint, MAX_INGREDIENTS, parseIngredients, profileResponse, remixCard, swapsResponse } from './engine';
import { chartSvg, escapeXml, shareCardSvg, wrapTitle } from './svg';
// The copy of the engine that the deployed API runs. Generated by `npm run build:engine`.
import * as built from '../../../supabase/functions/flavor-api/engine.js';

const vector: TasteVector = [3, 4, 6, 1, 5, 4, 2, 7];

describe('public API engine', () => {
  it('reads ingredient lists from a query string or a JSON array', () => {
    expect(parseIngredients('lime, Fish Sauce: 1 tbsp;  chilli\n')).toEqual([
      { name: 'lime', measure: '' },
      { name: 'Fish Sauce', measure: '1 tbsp' },
      { name: 'chilli', measure: '' },
    ]);
    expect(parseIngredients(['lime', { name: 'butter', measure: '40g' }, { name: 7 }, null, 3])).toEqual([
      { name: 'lime', measure: '' },
      { name: 'butter', measure: '40g' },
    ]);
  });

  it('refuses empty and oversized lists, and trims long names', () => {
    expect(parseIngredients('')).toBeNull();
    expect(parseIngredients(' , ,')).toBeNull();
    expect(parseIngredients(undefined)).toBeNull();
    expect(parseIngredients({ name: 'lime' })).toBeNull();
    expect(parseIngredients(Array.from({ length: MAX_INGREDIENTS + 1 }, (_, i) => `thing ${i}`))).toBeNull();
    expect(parseIngredients(Array.from({ length: MAX_INGREDIENTS }, (_, i) => `thing ${i}`))).toHaveLength(MAX_INGREDIENTS);
    expect(parseIngredients(['x'.repeat(500)])![0].name).toHaveLength(80);
  });

  it('returns the same numbers the app shows, with what it could not recognize', () => {
    const lines = parseIngredients('lime, fish sauce, red chilli, moon dust')!;
    const res = profileResponse(lines);
    expect(res.vector).toEqual(computeProfile(lines).vector);
    expect(res.tastes.map((t) => t.key)).toEqual(['sweet', 'salty', 'sour', 'bitter', 'umami', 'heat', 'rich', 'aroma']);
    expect(res.tastes[2]).toMatchObject({ label: 'Sour', from: ['lime'] });
    expect(res).toMatchObject({ matched: 3, total: 4, unrecognized: ['moon dust'] });
    expect(res.summary).toMatch(/^Mostly /);
  });

  it('answers swaps and drinks', () => {
    const butter = swapsResponse('Unsalted Butter');
    expect(butter.recognized).toBe(true);
    expect(butter.swaps.length).toBeGreaterThan(0);
    expect(swapsResponse('moon dust')).toEqual({ ingredient: 'moon dust', recognized: false, swaps: [], why: null });

    const lines = parseIngredients('cream, butter, parmesan, pasta')!;
    expect(drinksResponse(lines, true).drinks).toHaveLength(3);
    expect(drinksResponse(lines, false).drinks.every((d) => !d.alcohol)).toBe(true);
  });

  it('is the same engine the deployed API runs (rebuild with `npm run build:engine` if this fails)', () => {
    expect(built.engineFingerprint()).toBe(engineFingerprint());
    const lines = parseIngredients('Crème fraîche, soy sauce: 1 tsp, lime')!;
    expect(built.profileResponse(lines)).toEqual(profileResponse(lines));
  });
});

describe('public API requests (run against the built engine.js)', () => {
  const REMIX_ID = '11111111-1111-4111-8111-111111111111';
  const remix = {
    id: REMIX_ID,
    title: 'Sharper cabbage',
    note: null,
    parent_recipe_id: 'fc-charred-cabbage-miso-butter',
    ingredients: parseIngredients('cabbage, butter, miso, lime, rice vinegar')!,
    removed: [],
    added: ['Rice Vinegar'],
    created_at: '2026-11-16T00:00:00Z',
  };
  const png = new Uint8Array([137, 80, 78, 71]);
  const deps = {
    fetchRemix: async (id: string) => (id === REMIX_ID ? remix : null),
    fetchMeal: async () => null,
    toPng: async () => png,
  };
  const call = (path: string, init?: RequestInit) =>
    built.handleApi(new Request(`https://x.supabase.co/functions/v1/flavor-api${path}`, init), deps) as Promise<Response>;

  it('lists its endpoints and reports which engine it runs', async () => {
    const res = await call('/');
    expect(res.status).toBe(200);
    expect(res.headers.get('access-control-allow-origin')).toBe('*');
    const body = await res.json();
    expect(body.engine).toBe(engineFingerprint());
    expect(Object.keys(body.endpoints)).toHaveLength(6);
  });

  it('profiles ingredients from a query string or a JSON body, identically', async () => {
    const get = await (await call('/profile?ingredients=lime,fish%20sauce,chilli')).json();
    const post = await (
      await call('/profile', { method: 'POST', body: JSON.stringify({ ingredients: ['lime', 'fish sauce', { name: 'chilli' }] }) })
    ).json();
    expect(get).toEqual(post);
    expect(get.vector).toEqual(computeProfile(parseIngredients('lime, fish sauce, chilli')!).vector);
  });

  it('explains what is wrong with a bad request and does not cache the error', async () => {
    for (const path of ['/profile', '/chart.svg?ingredients=', '/drinks', '/swaps']) {
      const res = await call(path);
      expect(res.status, path).toBe(400);
      expect(res.headers.get('cache-control')).toBe('no-store');
      expect((await res.json()).error).toMatch(/^Give /);
    }
    expect((await call('/nope')).status).toBe(404);
    expect((await call('/profile', { method: 'DELETE' })).status).toBe(405);
    expect((await call('/profile', { method: 'OPTIONS' })).status).toBe(200);
  });

  it('serves the chart as an inert, cacheable SVG', async () => {
    const res = await call('/chart.svg?ingredients=lime,butter,miso&title=%3Cscript%3Ehi');
    expect(res.headers.get('content-type')).toMatch(/^image\/svg\+xml/);
    expect(res.headers.get('cache-control')).toBe('public, max-age=3600');
    expect(res.headers.get('content-security-policy')).toContain("default-src 'none'");
    const body = await res.text();
    expect(body).toContain('&lt;script&gt;hi');
    expect(body).not.toContain('<script');
  });

  it('answers swaps and alcohol-free drinks', async () => {
    expect((await (await call('/swaps?ingredient=butter')).json()).swaps).toContain('olive oil');
    const drinks = await (await call('/drinks?ingredients=cream,butter,pasta&alcohol=false')).json();
    expect(drinks.drinks.every((d: { alcohol: boolean }) => !d.alcohol)).toBe(true);
  });

  it('returns a public remix with its original, and its share image', async () => {
    const info = await (await call(`/remix/${REMIX_ID}`)).json();
    expect(info).toMatchObject({ title: 'Sharper cabbage', remixOf: { title: 'Charred Cabbage with Miso Butter' }, added: ['Rice Vinegar'] });
    expect(info.profile.vector).toHaveLength(8);

    const card = await (await call(`/remix/${REMIX_ID}/card.svg`)).text();
    expect(card).toContain('A remix of Charred Cabbage');
    expect(card).toContain('stroke-dasharray');

    const image = await call(`/remix/${REMIX_ID}/card.png`);
    expect(image.headers.get('content-type')).toBe('image/png');
    expect(new Uint8Array(await image.arrayBuffer())).toEqual(png);
  });

  it('never reveals private or missing remixes, and rejects ids that are not ids', async () => {
    expect((await call('/remix/22222222-2222-4222-8222-222222222222')).status).toBe(404);
    expect((await call('/remix/22222222-2222-4222-8222-222222222222/card.png')).status).toBe(404);
    expect((await call('/remix/1%20or%201=1')).status).toBe(400);
    expect((await call("/remix/x'%3Bdrop/card.png")).status).toBe(400);
  });

  it('still draws the card when the original recipe cannot be fetched', async () => {
    const broken = { ...deps, fetchRemix: async () => ({ ...remix, parent_recipe_id: 'mdb-52772' }), fetchMeal: async () => { throw new Error('down'); } };
    const res = (await built.handleApi(new Request(`https://x/flavor-api/remix/${REMIX_ID}/card.svg`), broken)) as Response;
    expect(res.status).toBe(200);
    expect(await res.text()).toContain('A FlavorCraft remix');
  });

  it('answers 500, not a stack trace, when rendering fails', async () => {
    const failing = { ...deps, toPng: async () => { throw new Error('wasm'); } };
    const res = (await built.handleApi(new Request(`https://x/flavor-api/remix/${REMIX_ID}/card.png`), failing)) as Response;
    expect(res.status).toBe(500);
    expect(await res.json()).toEqual({ error: 'Something went wrong computing that. Try again.' });
  });
});

describe('standalone charts', () => {
  it('escapes user text so a title cannot inject markup', () => {
    expect(escapeXml(`<script>alert("x")</script> & 'co'`)).toBe('&lt;script&gt;alert(&quot;x&quot;)&lt;/script&gt; &amp; &#39;co&#39;');
    expect(escapeXml(`a${String.fromCharCode(0)}b${String.fromCharCode(8)}c\td`)).toBe('abc\td');
    const out = chartSvg(vector, { title: '</text><script>alert(1)</script>' });
    expect(out).not.toContain('<script');
    expect(out).toContain('&lt;script&gt;');
  });

  it('draws a self-contained SVG with every taste labeled', () => {
    const out = chartSvg(vector, { title: 'Tamarind Prawns', size: 5000 });
    expect(out.startsWith('<svg xmlns="http://www.w3.org/2000/svg"')).toBe(true);
    expect(out.endsWith('</svg>')).toBe(true);
    for (const label of ['Sweet', 'Salty', 'Sour', 'Bitter', 'Umami', 'Heat', 'Richness', 'Aroma']) expect(out).toContain(`>${label}`);
    expect(out).toContain('Tamarind Prawns');
    expect(out).toContain('width="900"'); // size is clamped
    expect(out).not.toMatch(/var\(--|class=/); // nothing that needs the app's stylesheet
    expect(chartSvg(vector)).toContain('viewBox="0 0 420 430"');
  });

  it('wraps long titles onto a few lines and marks what was cut', () => {
    expect(wrapTitle('Charred Cabbage with Miso Butter', 19, 3)).toEqual(['Charred Cabbage', 'with Miso Butter']);
    const long = wrapTitle('A very long remix title that keeps going well past what fits on the card', 19, 3);
    expect(long).toHaveLength(3);
    expect(long[2].endsWith(String.fromCharCode(8230))).toBe(true);
    expect(wrapTitle('Supercalifragilisticexpialidocious', 19, 3)[0].length).toBeLessThanOrEqual(23);
    expect(wrapTitle('   ', 19, 3)).toEqual([]);
  });

  it('builds a share card that compares a remix with its original', () => {
    const original = { title: 'Roast Chicken', ingredients: parseIngredients('chicken, butter, potato')! };
    const remix = { title: 'Sharper <Roast> Chicken', ingredients: parseIngredients('chicken, butter, potato, lemon')! };
    const card = remixCard(remix, original);
    expect(card).toContain('viewBox="0 0 1200 630"');
    expect(card).toContain('Sharper &lt;Roast&gt;');
    expect(card).toContain('A remix of Roast Chicken');
    expect(card).toContain('More sour');
    expect(card).toContain('stroke-dasharray'); // the original, as a dashed outline

    const alone = remixCard(remix, null);
    expect(alone).toContain('A FlavorCraft remix');
    expect(alone).not.toContain('stroke-dasharray');
    expect(shareCardSvg({ title: 'x', subtitle: 'y', vector })).toContain('FlavorCraft');
  });
});
